after:
/* Nova aba de tramitação: visão de registros baixados, sem mudanças no banco. */
.tramitacaoIntro{margin-top:10px;border:1px solid #cbddec;background:#fff;border-radius:9px;padding:15px 17px;color:#163f6b}
.tramitacaoIntro[hidden]{display:none!important}
.tramitacaoHeading{display:flex;justify-content:space-between;align-items:flex-start;gap:16px}
.tramitacaoHeading h2{margin:3px 0 5px;font-size:19px}
.tramitacaoHeading p{margin:0;line-height:1.5;color:#536f89;font-size:12px;max-width:760px}
.tramitacaoEyebrow{font-weight:800;letter-spacing:.08em;font-size:10px;color:#1379ce}
.tramitacaoIndicador{border:1px solid #c9dceb;background:#eef5fb;border-radius:20px;padding:7px 11px;white-space:nowrap;font-size:10px;font-weight:800;color:#34678e}
.tramitacaoStats{margin-top:13px;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.tramitacaoStat{background:#f3f8fc;border:1px solid #d9e7f3;border-radius:7px;padding:10px 13px;display:flex;flex-direction:column;gap:4px}
.tramitacaoStat small{color:#5a7390;font-weight:600}.tramitacaoStat strong{font-size:20px;color:#0b548f}
.tramitacaoAviso{margin:12px 0 0;padding:10px 12px;border-left:3px solid #86a9c6;background:#f7fafc;font-size:11px;color:#47667e}
@media(max-width:850px){.tramitacaoHeading{flex-wrap:wrap}.tramitacaoStats{grid-template-columns:1fr 1fr}.tramitacaoStat:last-child{grid-column:1/-1}}

/* Mantém os menus acima da tabela e impede o recorte pelo cabeçalho. */

if(currentScreen==='encerradas') return !!statusIntegracao;

// TRAMITAÇÃO: SS que constam como baixadas no sistema, sem presumir conclusão da tramitação.
if(currentScreen==='tramitacao') return statusIntegracao.startsWith('baixad');

return true;

$('tramitacaoIntro').hidden=screen!=='tramitacao';
document.querySelector('.hint').textContent=screen==='tramitacao'?'Selecione uma SS para visualizar seus dados e relatório. Nenhuma operação de tramitação é executada nesta tela.':'Marque uma ou várias SS. A opção de envio abre somente após selecionar.';
configureActions(screen);
